add_filter( 'woocommerce_checkout_fields', 'perfectpixel_refresh_totals_on_any_field', 9999 );

function perfectpixel_refresh_totals_on_any_field( $fields ) {
	foreach ( $fields as $group => $group_fields ) {
		foreach ( $group_fields as $key => $field ) {
			$classes = isset( $field['class'] ) ? (array) $field['class'] : array();
			if ( ! in_array( 'update_totals_on_change', $classes, true ) ) {
				$classes[] = 'update_totals_on_change';
			}
			$fields[ $group ][ $key ]['class'] = $classes;
		}
	}
	return $fields;
}
